support = [
 ("new-patients","New Patients","Everything new clients need to begin care with Fayetteville Animal Hospital.","Welcome to our fictional practice","Before the first visit, gather prior medical records, current medication and prevention details, food information, and a list of questions. Sending records ahead gives the clinical team time to understand the history.","Arrive a few minutes early and keep cats in secure carriers and dogs on non-retractable leashes. Tell us before arrival if your pet needs extra space or has had a difficult visit elsewhere."),
 ("what-to-expect","What to Expect","A clear guide to appointments, communication, recommendations, and follow-up.","Visits built around listening","A veterinary assistant begins with your concerns and your pet's recent routine. The veterinarian then performs an exam, discusses findings, and explains any recommendations before moving forward.","Some answers are immediate; others require testing or observation over time. We provide next steps and invite questions so you leave knowing what to monitor."),
 ("payment-information","Payment Information","Prototype payment policies and planning information for this fictional veterinary practice.","Clear conversations about cost","Fayetteville Animal Hospital is fictional and does not accept payment. In a real practice, estimates would be reviewed before non-emergency services and payment would be due when care is provided.","A realistic practice may accept major cards and pet insurance reimbursement while offering written estimates for procedures. Financial conversations should happen early and without judgment."),
 ("faq","Frequently Asked Questions","Answers to common questions about appointments, records, prescriptions, and hospital policies.","Helpful answers before your visit","Call before arriving for urgent concerns so the team can assess timing and direct you appropriately. Routine appointment requests may be made through the prototype form, which does not transmit information.","Bring medications in original packaging and request prescription refills before running out. Written authorization is typically required before records are shared with another hospital."),
 ("emergency-information","Emergency Information","How to recognize urgent warning signs and seek appropriate emergency veterinary care.","Know where to go","Fayetteville Animal Hospital is not a 24-hour emergency facility. Difficulty breathing, collapse, uncontrolled bleeding, major trauma, prolonged seizures, toxin exposure, or inability to urinate may require immediate emergency care.","Call the nearest open emergency veterinary hospital while preparing to leave. Do not delay for an online response, and do not induce vomiting unless a veterinary professional specifically instructs you to do so."),
]

def rel(depth, path): return "../" * depth + path

def header(depth, active=""):
 p = "../" * depth
 def current(name): return ' aria-current="page"' if active == name else ""
 return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="container nav-wrap"><a class="brand" href="{p}index.html" aria-label="Fayetteville Animal Hospital home"><svg class="brand-mark" viewBox="0 0 36 44" aria-hidden="true"><path d="M18 1C10 8 4 15 4 25c0 10 6 17 14 18 8-1 14-8 14-18C32 15 26 8 18 1Z" fill="none" stroke="currentColor"/><path d="M18 11v22M10 23h16" stroke="currentColor"/></svg><span>Fayetteville<br>Animal Hospital</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="nav">Menu</button><nav id="nav" class="nav-links" aria-label="Primary"><a{current('home')} href="{p}index.html">Home</a><a{current('about')} href="{p}about.html">About</a><a{current('services')} href="{p}services.html">Services</a><a{current('resources')} href="{p}resources.html">Resources</a><a{current('contact')} href="{p}contact.html">Contact</a><a class="button" href="{p}contact.html#appointment">Request an Appointment</a></nav></div></header>'''

def footer(depth):
 p = "../" * depth
 return f'''<footer class="site-footer"><div class="container"><div class="footer-grid"><div><div class="footer-brand">Fayetteville Animal Hospital</div><p style="color:#aabdb0">Care for every chapter.</p></div><div class="footer-col"><h2>Plan a visit</h2><a href="{p}new-patients.html">New patients</a><a href="{p}what-to-expect.html">What to expect</a><a href="{p}payment-information.html">Payment information</a><a href="{p}faq.html">FAQ</a></div><div class="footer-col"><h2>Care</h2><a href="{p}services.html">Services</a><a href="{p}pet-care/puppy-care.html">Puppy care</a><a href="{p}pet-care/senior-cat-care.html">Senior cat care</a><a href="{p}emergency-information.html">Emergency information</a></div><div class="footer-col"><h2>Explore</h2><a href="{p}about.html">About</a><a href="{p}resources.html">Resources</a><a href="{p}contact.html">Contact</a></div></div><div class="footer-bottom"><span>© 2026 Fayetteville Animal Hospital</span><span class="disclosure">Fayetteville Animal Hospital is a fictional veterinary practice created for development and testing purposes.</span></div></div></footer>'''

def page(path, title, description, h1, eyebrow, crumb, body, active, depth=1):
 canonical = BASE + path
 css = rel(depth, "css/style.css")
 js = rel(depth, "js/script.js")
 html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Fayetteville Animal Hospital</title><meta name="description" content="{escape(description, quote=True)}"><link rel="canonical" href="{canonical}"><link rel="stylesheet" href="{css}"><script src="{js}" defer></script></head><body>{header(depth,active)}<main id="main"><section class="page-hero compact"><div class="container narrow"><div class="crumbs">{crumb}</div><span class="eyebrow">{escape(eyebrow)}</span><h1>{escape(h1)}</h1><p class="lead">{escape(description)}</p></div></section>{body}</main>{footer(depth)}</body></html>'''
 target = ROOT / path
 target.parent.mkdir(parents=True, exist_ok=True)
 target.write_text(html, encoding="utf-8")

def related_cards(items, depth=1):
 return '<div class="related"><span class="eyebrow">Related reading</span><div class="related-grid">' + ''.join(f'<a href="{rel(depth,url)}">{escape(label)}</a>' for url,label in items) + '</div></div>'

service_names = {slug:name for slug,name,*_ in services}
article_names = {slug:title for slug,title,*_ in articles}

for slug,name,summary,need,expect,related in services:
 links=[(f"services/{r}.html",service_names[r]) for r in related]
 body=f'''<section class="section section-paper"><div class="container content-shell"><article class="prose"><h2>Care with a longer view</h2><p>{escape(summary)} Our recommendations reflect the individual pet, current evidence, and the family's priorities rather than a one-size-fits-all protocol.</p><h2>When this service may help</h2><p>{escape(need)}</p><p>Contact us when a change is persistent, worsening, painful, or simply concerning. A conversation can help determine whether a routine appointment, prompt visit, or emergency hospital is the right next step.</p><h2>What to expect</h2><p>{escape(expect)}</p><h3>Designed around your pet</h3><ul><li>A focused history and attentive physical examination</li><li>Clear discussion before tests or treatment</li><li>Written next steps and signs to monitor at home</li><li>Coordination with specialty or emergency care when appropriate</li></ul>{related_cards(links + [("resources.html","Browse the pet owner resource library")])}</article><aside class="page-aside"><h2>Service navigation</h2><a href="../services.html">All veterinary services</a><a href="../new-patients.html">New patient information</a><a href="../what-to-expect.html">What to expect</a><a class="button" href="../contact.html#appointment">Request an appointment</a></aside></div></section>'''
 page(f"services/{slug}.html",name,f"Learn about {name.lower()} for dogs and cats at our fictional Fayetteville veterinary practice.",name,"Veterinary services",f'<a href="../index.html">Home</a> / <a href="../services.html">Services</a> / {escape(name)}',body,"services")

for slug,name,summary,intro,expect,service,article in life_stages:
 body=f'''<section class="section section-paper"><div class="container content-shell"><article class="prose"><h2>Care for this chapter</h2><p>{escape(intro)}</p><p>{escape(summary)} The most useful plan changes as your pet grows, and continuity helps small observations become meaningful.</p><h2>What we pay attention to</h2><ul><li>Changes in weight, appetite, thirst, sleep, and activity</li><li>Dental health, mobility, skin, coat, and behavior</li><li>Vaccination and parasite risks shaped by daily life</li><li>Questions about nutrition, enrichment, and home routines</li></ul><h2>Planning the next visit</h2><p>{escape(expect)}</p>{related_cards([(f"services/{service}.html",service_names[service]),(f"resources/articles/{article}.html",article_names[article]),("resources.html","Explore all pet care resources")])}</article><aside class="page-aside"><h2>Life-stage care</h2><a href="puppy-care.html">Puppy care</a><a href="kitten-care.html">Kitten care</a><a href="adult-dog-care.html">Adult dog care</a><a href="adult-cat-care.html">Adult cat care</a><a href="senior-dog-care.html">Senior dog care</a><a href="senior-cat-care.html">Senior cat care</a><a class="button" href="../contact.html#appointment">Request an appointment</a></aside></div></section>'''
 page(f"pet-care/{slug}.html",name,f"A practical guide to {name.lower()} from Fayetteville Animal Hospital's fictional veterinary team.",name,"Life-stage care",f'<a href="../index.html">Home</a> / <a href="../resources.html">Resources</a> / {escape(name)}',body,"resources")

for slug,title,meta,intro,detail,service in articles:
 body=f'''<section class="section section-paper"><div class="container content-shell"><article class="prose"><div class="resource-note"><strong>Educational note:</strong> This general information cannot diagnose a pet or replace an examination.</div><h2>The short answer</h2><p>{escape(intro)}</p><h2>Why the details matter</h2><p>{escape(detail)}</p><p>Your pet's age, history, environment, medications, and recent changes all affect what advice is appropriate. Keep notes about timing, frequency, appetite, activity, and anything that makes the concern better or worse.</p><h2>When to contact a veterinarian</h2><p>Call when a change is persistent, recurring, painful, worsening, or accompanied by weakness, breathing trouble, repeated vomiting, bleeding, collapse, or difficulty urinating. Emergency signs should not wait for an online response.</p><h2>How we can help</h2><p>A veterinary visit brings the history, physical examination, and—when useful—targeted testing together. The goal is not simply to name a problem, but to create a safe and realistic next step.</p>{related_cards([(f"services/{service}.html",service_names[service]),("resources.html","Return to the resource library"),("contact.html","Contact the hospital")],2)}</article><aside class="page-aside"><h2>Resource library</h2><a href="../../resources.html">All resources</a><a href="../conditions/ear-infections.html">Care and condition guides</a><a href="../../faq.html">Frequently asked questions</a><a class="button" href="../../contact.html#appointment">Request an appointment</a></aside></div></section>'''
 page(f"resources/articles/{slug}.html",title,meta,title,"Pet owner guide",f'<a href="../../index.html">Home</a> / <a href="../../resources.html">Resources</a> / {escape(title)}',body,"resources",2)

for slug,title,meta,intro,detail,service in conditions:
 body=f'''<section class="section section-paper"><div class="container content-shell"><article class="prose"><div class="resource-note"><strong>Important:</strong> This guide supports informed observation but does not provide a diagnosis.</div><h2>What owners may notice</h2><p>{escape(intro)}</p><p>Write down when signs began, how often they occur, recent changes, and any photos or videos that may help. Avoid giving leftover or human medication unless a veterinarian directs you.</p><h2>Why an examination matters</h2><p>{escape(detail)}</p><p>Different conditions can look alike from home. An examination helps narrow the possibilities and determine whether testing, treatment, monitoring, or referral is appropriate.</p><h2>When to seek care</h2><p>Prompt care is appropriate when signs cause pain, recur, worsen, interfere with eating or movement, or come with marked lethargy. Trouble breathing, collapse, uncontrolled bleeding, major trauma, prolonged seizures, or inability to urinate require emergency care.</p>{related_cards([(f"services/{service}.html",service_names[service]),("resources.html","Browse all educational resources"),("emergency-information.html","Emergency information")],2)}</article><aside class="page-aside"><h2>Care guides</h2><a href="ear-infections.html">Ear infections</a><a href="skin-allergies.html">Skin allergies</a><a href="vomiting-diarrhea.html">Vomiting and diarrhea</a><a href="pet-limping.html">Limping</a><a href="urinary-issues.html">Urinary issues</a><a class="button" href="../../contact.html#appointment">Request an appointment</a></aside></div></section>'''
 page(f"resources/conditions/{slug}.html",title,meta,title,"Condition guide",f'<a href="../../index.html">Home</a> / <a href="../../resources.html">Resources</a> / {escape(title)}',body,"resources",2)

for slug,name,role,interest,education,bio in team:
 body=f'''<section class="section section-paper"><div class="container profile-intro"><article class="prose"><h2>A thoughtful approach to care</h2><p>{escape(bio)}</p><p>Like every identity on this demonstration website, this profile is fictional and does not represent a real veterinary professional.</p><h2>How {escape(name.split()[0].replace('Dr.','Dr.'))} works with families</h2><p>Good plans begin with listening. Appointments make room for observations from home, clear explanations of findings, and questions about what is realistic for the pet and family.</p>{related_cards([("about.html","Return to About"),("services.html","Explore veterinary services"),("contact.html","Plan a visit")],1)}</article><dl class="profile-facts"><dt>Role</dt><dd>{escape(role)}</dd><dt>Clinical interests</dt><dd>{escape(interest)}</dd><dt>Education</dt><dd>{escape(education)}</dd><dt>Status</dt><dd>Fictional demonstration profile</dd></dl></div></section>'''
 page(f"team/{slug}.html",name,f"Meet {name}, a fictional {role.lower()} profile created for the Fayetteville Animal Hospital demonstration site.",name,"Fictional team profile",f'<a href="../index.html">Home</a> / <a href="../about.html">About</a> / {escape(name)}',body,"about")

for slug,title,meta,h2,p1,p2 in support:
 body=f'''<section class="section section-paper"><div class="container content-shell"><article class="prose"><h2>{escape(h2)}</h2><p>{escape(p1)}</p><p>{escape(p2)}</p><h2>Questions are welcome</h2><p>Clear expectations make care easier. Contact the hospital for help choosing the right appointment type, preparing records, or understanding the next step. This site is a fictional development environment and cannot provide medical services.</p>{related_cards([("services.html","Explore services"),("resources.html","Browse pet resources"),("contact.html","Contact and appointments")],0)}</article><aside class="page-aside"><h2>Visit information</h2><a href="new-patients.html">New patients</a><a href="what-to-expect.html">What to expect</a><a href="payment-information.html">Payment information</a><a href="faq.html">FAQ</a><a href="emergency-information.html">Emergency information</a></aside></div></section>'''
