def hub_card(url,kicker,title,text):
 return f'<article class="hub-card"><span class="eyebrow">{escape(kicker)}</span><h2>{escape(title)}</h2><p>{escape(text)}</p><a class="text-link" href="{url}">Learn more</a></article>'

service_cards=''.join(hub_card(f"services/{s}.html","Veterinary care",n,summary) for s,n,summary,*_ in services)
services_body=f'''<section class="section section-paper"><div class="container"><div class="category-heading"><div><span class="eyebrow">Complete care</span><h2>Services shaped around the whole story.</h2></div><p>Explore preventive, diagnostic, procedural, and life-stage care for dogs and cats.</p></div><div class="hub-grid">{service_cards}</div></div></section><section class="cta"><div class="container cta-inner"><h2>Not sure which visit to request?</h2><a class="button button-light" href="contact.html#appointment">Tell us what you’re noticing</a></div></section>'''
page("services.html","Veterinary Services","Explore preventive, dental, diagnostic, surgical, life-stage, and urgent veterinary care for dogs and cats.","Here for the routine—and the unexpected.","Connected care",'<a href="index.html">Home</a> / Services',services_body,"services",0)

article_cards=''.join(hub_card(f"resources/articles/{s}.html","Pet owner guide",t,m) for s,t,m,*_ in articles)
