resources_body=f'''<section class="section section-paper"><div class="container"><div class="category-heading"><div><span class="eyebrow">Life-stage library</span><h2>Care that changes as they do.</h2></div><p>Practical guidance for puppies, kittens, adults, and senior pets.</p></div><div class="hub-grid">{life_cards}</div></div></section><section class="section"><div class="container"><div class="category-heading"><div><span class="eyebrow">Owner education</span><h2>Questions worth exploring.</h2></div><p>General information to support better conversations with your veterinarian.</p></div><div class="hub-grid">{article_cards}</div></div></section><section class="section section-paper"><div class="container"><div class="category-heading"><div><span class="eyebrow">Care and condition guides</span><h2>Understand what you’re noticing.</h2></div><p>These guides educate without diagnosing and explain when professional evaluation matters.</p></div><div class="hub-grid">{condition_cards}</div></div></section>'''
page("resources.html","Pet Care Resources","Explore practical veterinary articles, life-stage guidance, and common condition guides for dog and cat owners.","Good questions are good care.","The field guide",'<a href="index.html">Home</a> / Resources',resources_body,"resources",0)

team_cards=''.join(hub_card(f"team/{s}.html",role,n,interest) for s,n,role,interest,*_ in team)
support_cards=''.join(hub_card(f"{s}.html","Visit information",t,m) for s,t,m,*_ in support)
about_body=f'''<section class="section section-paper"><div class="container split"><div class="image-panel"><img src="images/exam-room-cat.jpg" alt="A veterinarian spending time with a tabby cat and the cat's owner"></div><div><span class="eyebrow">Our philosophy</span><h2>Clinical rigor. Human warmth.</h2><p class="lead">Pets tell us plenty when we make time to observe, listen, and connect the clues.</p><p>We translate findings into clear choices—without rushed explanations or one-size-fits-all plans. The hospital and every person represented here are fictional.</p></div></div></section><section class="section section-forest"><div class="container"><div class="category-heading"><div><span class="eyebrow">Our fictional team</span><h2>Different strengths. One standard of care.</h2></div><p style="color:#d8dfd9">Every identity, credential, and biography is invented for this demonstration.</p></div><div class="hub-grid">{team_cards}</div></div></section><section class="section"><div class="container"><div class="category-heading"><div><span class="eyebrow">Before your visit</span><h2>Know what to expect.</h2></div><p>Useful information for planning care at our fictional hospital.</p></div><div class="hub-grid">{support_cards}</div></div></section>'''
page("about.html","About Our Practice","Learn about the philosophy, fictional team, and relationship-centered care at Fayetteville Animal Hospital.","Medicine is personal.","A practice with a point of view",'<a href="index.html">Home</a> / About',about_body,"about",0)

