all_pages += [Path("services")/f"{s[0]}.html" for s in services]
all_pages += [Path("pet-care")/f"{s[0]}.html" for s in life_stages]
all_pages += [Path("resources/articles")/f"{s[0]}.html" for s in articles]
all_pages += [Path("resources/conditions")/f"{s[0]}.html" for s in conditions]
